// Generated by Cypress Author on 2026-11-24.
// Group the Swag Labs logout scenario.
describe('Swag Labs authentication', () => {
  // Define the single login-and-logout scenario.
  it('logs out and returns to the login page', () => {
    // Open the Swag Labs login page.
    cy.visit('/');

    // Enter the standard user's username.
    cy.get('[data-test="username"]').type('standard_user');
    // Enter the standard user's password.
    cy.get('[data-test="password"]').type('secret_sauce');
    // Submit the login form.
    cy.get('[data-test="login-button"]').click();

    // Confirm the inventory page loaded after login.
    cy.location('pathname').should('eq', '/inventory.html');
    // Open the burger menu.
    cy.get('#react-burger-menu-btn').click();
    // Select the logout link from the sidebar menu.
    cy.get('[data-test="logout-sidebar-link"]').click();

    // Confirm the browser returned to the login page.
    cy.location('pathname').should('eq', '/');
    // Confirm the login button is visible after logout.
    cy.get('[data-test="login-button"]').should('be.visible');
  });
});
